"""docich#4650: an unowned shop closing confirmation is answered early.

The ch1 fresh run (v1164) held shop_exit_confirm for 102 observations with no
input -- ~150 s at the production 1.5 s cadence -- because no flow owned the
screen in that phase and only the no-input backstop could answer it.
"""
from docich.hanjuku_speedrun.hanjuku import orchestrator as O


def test_the_unowned_confirmation_is_answered_after_a_short_settle():
    assert O.shop_exit_unowned_input("shop_exit_confirm", 1) is None
    assert O.shop_exit_unowned_input("shop_exit_confirm", O.SHOP_EXIT_HOLD_MAX) is None
    assert O.shop_exit_unowned_input("shop_exit_confirm",
                                     O.SHOP_EXIT_HOLD_MAX + 1) == "a"


def test_the_settle_is_far_inside_the_no_input_backstop():
    assert O.SHOP_EXIT_HOLD_MAX < O.NO_INPUT_HOLD_MAX


def test_other_screens_are_never_answered_by_this_rule():
    for kind in ("shop_list", "shop_quantity", "shop_quantity_prompt",
                 "gift_request", "yes_no", "map", "text"):
        assert O.shop_exit_unowned_input(kind, O.SHOP_EXIT_HOLD_MAX + 5) is None


def test_guarded_holds_stay_fail_closed():
    streak = O.SHOP_EXIT_HOLD_MAX + 5
    assert O.shop_exit_unowned_input("shop_exit_confirm", streak, guarded=True) is None
    assert O.shop_exit_unowned_input("shop_exit_confirm", streak, army_owned=True) is None
    assert O.shop_exit_unowned_input("shop_exit_confirm", streak,
                                     map_registration_hold=True) is None
    assert O.shop_exit_unowned_input("shop_exit_confirm", streak,
                                     orphan_battle_menu=True) is None